diff --git a/docs/USER_GUIDE.md b/docs/USER_GUIDE.md
index 7966e38..0662477 100644
--- a/docs/USER_GUIDE.md
+++ b/docs/USER_GUIDE.md
@@ -815,6 +815,14 @@ hybrid run normally proves only that a cycle figure came out. `--verify`
 # [verify] PASS: vsim drain matches the QEMU oracle
 ```

+Performance note: without `--verify`, the vsim leg drains only `mcycle`/`minstret`
+(the cycle figure) and skips reading back the full architectural register file
+over the Debug Module -- ~190 abstract commands (all FPRs, the vector-register
+sweep, the Andes/M-ext CSR blocks) whose simulated debug cycles dominate hybrid
+wall-clock for a short ROI but never affect the cycle count. `--verify` needs
+every field for the diff, so it keeps the full drain; expect a `--verify` run to
+take noticeably longer than the same run without it.
+
 How it works: after the normal run, the same ELF re-runs on pure QEMU (the
 oracle) with the plugin draining at the ROI exit boundary, sampled at the
 exact pc where vsim halted. The pre-ROI path is QEMU in both runs, so the
diff --git a/driver/hybrid.cpp b/driver/hybrid.cpp
index 375511c..8d1da67 100644
--- a/driver/hybrid.cpp
+++ b/driver/hybrid.cpp
@@ -101,6 +101,15 @@ std::vector<std::string> vsim_extra_args(const Cli& cli, const std::string& kind
     return {};
   }

+  // #1: when the drained state is not cross-checked (--verify off) the driver
+  // consumes only the vsim mcycle delta, so tell the accurate leg to drain just
+  // the counters (StateDrain::drain_counters_only) and skip the full
+  // register-file readback (~190 DM abstract commands -- f0..f31, the V dump
+  // sweep, the Andes/M-ext blocks). --verify keeps the full drain so the oracle
+  // diff sees every field.
+  if (!cli.verify)
+    out.push_back("--drain-minimal");
+
   return out;
 }

diff --git a/driver/hybrid_test.cpp b/driver/hybrid_test.cpp
index 4084d70..c383fce 100644
--- a/driver/hybrid_test.cpp
+++ b/driver/hybrid_test.cpp
@@ -145,21 +145,24 @@ int main() {
   // --- vsim_extra_args: user-forwarded vsim-leg flags, validated by trigger ---
   {
     std::string err;
-    // no forwarded flags -- empty.
-    CHECK(vsim_extra_args(mk({"run", "--mode", "hybrid"}), "marker", err).empty());
+    // no user-forwarded flags -- just the driver-derived --drain-minimal
+    // (no --verify here, so the accurate leg drains the counters only).
+    check_eq(vsim_extra_args(mk({"run", "--mode", "hybrid"}), "marker", err),
+             {"--drain-minimal"}, "no-forward-minimal");
     CHECK(err.empty());

     // kanata (marker/pc): --kanata <f> --kanata-roi.
     check_eq(
         vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata", "k.txt"}),
                         "marker", err),
-        {"--kanata", "k.txt", "--kanata-roi"}, "kanata");
+        {"--kanata", "k.txt", "--kanata-roi", "--drain-minimal"}, "kanata");
     CHECK(err.empty());
     // kanata + objdump.
     check_eq(vsim_extra_args(mk({"run", "--mode", "hybrid", "--kanata",
                                  "k.txt", "--objdump", "o.txt"}),
                              "pc", err),
-             {"--kanata", "k.txt", "--kanata-roi", "--objdump", "o.txt"},
+             {"--kanata", "k.txt", "--kanata-roi", "--objdump", "o.txt",
+              "--drain-minimal"},
              "kanata-objdump");
     CHECK(err.empty());

@@ -173,5 +176,24 @@ int main() {
     CHECK(!err.empty());
   }

+  // --- #1: --drain-minimal added to the accurate leg iff --verify is OFF ---
+  {
+    auto has = [](const std::vector<std::string>& v, const char* s) {
+      for (const auto& x : v) if (x == s) return true;
+      return false;
+    };
+    std::string err;
+    // Default (no --verify): the driver only reads the mcycle delta, so the
+    // accurate leg drains the counters only.
+    const auto off = vsim_extra_args(mk({"run", "--mode", "hybrid"}), "pc", err);
+    CHECK(err.empty());
+    CHECK(has(off, "--drain-minimal"));
+    // --verify: the oracle diffs the full drained state, so it must stay full.
+    const auto on =
+        vsim_extra_args(mk({"run", "--mode", "hybrid", "--verify"}), "pc", err);
+    CHECK(err.empty());
+    CHECK(!has(on, "--drain-minimal"));
+  }
+
   return andes_sim::test::report("hybrid");
 }

