1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/andes_caps.hpp"
9	#include "hybrid/dmi_poll.hpp"
10	#include "hybrid/resume_driver.hpp"
11	#include "hybrid/state_abi.h"
12	#include "hybrid/v_regfile_xfer.hpp"
13	
14	#include <algorithm>
15	#include <array>
16	#include <cstdint>
17	#include <span>
18	
19	namespace hybrid
20	{
21	
22	class StateDrain
23	{
24	public:
25	  using RD = ResumeDriver;
26	
27	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
28	  // the mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the
29	  // unset sentinel; only the V dump sweep consults it, and it throws there if
30	  // a V drain is reached with the GPA unset (no silent dump to a bogus
31	  // address). The simulator passes the real value from platform.main_memory.
32	  // caps: which Andes custom CSRs the TARGET core implements (from its
33	  // config.inc, supplied by the sim binary). Defaults to all() so existing
34	  // call sites are unchanged. Gates the Andes re-read below: reading an
35	  // unimplemented CSR can stall the DM, same as restoring one.
36	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
37	                      AndesCaps caps = AndesCaps::all())
38	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
39	  {}
40	
41	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
42	  // drain_with_passthrough when the QEMU 1 snapshot is available.
43	  auto drain() -> hybrid_state_v1
44	  {
45	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
46	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
47	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted,
48	                   "StateDrain halt");
49	
50	    hybrid_state_v1 state{};
51	    state.magic   = HYBRID_STATE_MAGIC;
52	    state.version = HYBRID_STATE_VERSION;
53	    state.flags   = HYBRID_FLAG_RV64;
54	    // L6: dcsr.prv holds the privilege the hart was in when the halt landed.
55	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
56	                                  "StateDrain DCSR") & 0x3u;
57	
58	    for (uint16_t i = 1; i < 32; ++i)
59	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
60	
61	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
62	    return state;
63	  }
64	
65	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
66	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
67	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
68	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set, also
69	  // freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
70	  // and vreg remain pass-through (read-only / too large for DM).
71	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
72	  // contribution would otherwise be discarded as the passthrough preserves
73	  // QEMU1's pre-handoff value.
74	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
75	  {
76	    auto state       = input;
77	    const auto fresh = drain();
78	    std::copy(std::begin(fresh.gpr) + 1, std::end(fresh.gpr),
79	              std::begin(state.gpr) + 1);
80	    state.pc   = fresh.pc;
81	    state.priv = fresh.priv;  // L6: privilege at the exit halt, not QEMU1's
82	
83	    if (input.flags & HYBRID_FLAG_FP) {
84	      for (uint16_t i = 0; i < 32; ++i)
85	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
86	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
87	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
88	    }
89	
90	    if (input.flags & HYBRID_FLAG_V) {
91	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
92	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
93	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
94	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
95	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
96	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
97	    }
98	
99	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
100	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
101	    // dropped and the stale QEMU1 value passes through into the drained state.
102	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
103	
104	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
105	    // restores them), so re-read them -- an in-ROI write must reach the drained
106	    // state instead of the stale QEMU1 passthrough value.
107	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
108	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
109	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
110	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
111	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
112	
113	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
114	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
115	
116	    // Andes V5 CSR block (v3): re-read the transported Andes CSRs from the hart
117	    // so an in-ROI write reaches the drained state instead of the stale QEMU1
118	    // passthrough (same round-trip as mscratch). caps_ gates each read to the
119	    // CSRs the core implements (reading an absent custom CSR can stall the DM,
120	    // same as restoring one); a skipped CSR keeps its passthrough value.
121	    // HYBRID_ANDES_CSR_LIST is the single source of truth shared with the
122	    // plugin drain, ResumeDriver, and state_diff.
123	    if (input.flags & HYBRID_FLAG_ANDES) {
124	#define X(field, addr, name) \
125	  if (caps_.supports_csr(addr)) \
126	    state.andes.field = read_register_64(bus_, regno_csr(addr));
127	      HYBRID_ANDES_CSR_LIST(X)
128	#undef X
129	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
130	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
131	          state.andes.pmacfg[i] =
132	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
133	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
134	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
135	          state.andes.pmaaddr[i] =
136	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
137	    }
138	
139	    // M-ext CSR block (v4): re-read the transported M-mode CSRs the core
140	    // implements, capability-gated by address like the Andes block. A skipped
141	    // CSR keeps its passthrough value. Same single-source X-macro.
142	    if (input.flags & HYBRID_FLAG_M_EXT) {
143	#define X(field, addr, name) \
144	  if (caps_.supports_csr(addr)) \
145	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
146	      HYBRID_M_EXT_CSR_LIST(X)
147	#undef X
148	    }
149	
150	    // V data regfile: dump v0..v31 to the shared scratch region via the
151	    // Program Buffer LAST -- after every architectural read above -- so the
152	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
153	    // cannot corrupt the values already captured. The simulator's
154	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
